import React, { useState, useEffect } from 'react';
import { useLLM } from '../../hooks/useLLM';
import { ChatSettings } from '../../types';

const LLMSettings: React.FC = () => {
  const {
    settings,
    switchLLM,
    updateGeminiConfig,
    updateVLLMConfig,
    currentProvider,
    isConfigured
  } = useLLM();

  const [showSettings, setShowSettings] = useState(false);
  const [localSettings, setLocalSettings] = useState<ChatSettings>(settings);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  // Update local settings when global settings change
  useEffect(() => {
    setLocalSettings(settings);
    setHasUnsavedChanges(false);
  }, [settings]);

  return (
    <div className="llm-settings">
      <button 
        onClick={() => setShowSettings(!showSettings)}
        className="settings-toggle"
      >
        ⚙️ LLM Settings ({currentProvider})
      </button>

      {showSettings && (
        <div className="settings-panel">
          <div className="provider-selector">
            <h3>Choose LLM Provider</h3>
            <div className="provider-options">
              <label className={`provider-option ${currentProvider === 'gemini' ? 'active' : ''}`}>
                <input
                  type="radio"
                  value="gemini"
                  checked={currentProvider === 'gemini'}
                  onChange={() => switchLLM('gemini')}
                />
                <span>Google Gemini</span>
              </label>
              <label className={`provider-option ${currentProvider === 'vllm' ? 'active' : ''}`}>
                <input
                  type="radio"
                  value="vllm"
                  checked={currentProvider === 'vllm'}
                  onChange={() => switchLLM('vllm')}
                />
                <span>vLLM Server</span>
              </label>
            </div>
          </div>

          {currentProvider === 'gemini' && (
            <div className="gemini-config">
              <h4>Gemini Configuration</h4>
              <div className="config-field">
                <label>API Key:</label>
                <input
                  type="password"
                  value={settings.geminiConfig.apiKey}
                  onChange={(e) => updateGeminiConfig({ apiKey: e.target.value })}
                  placeholder="Enter your Gemini API key"
                />
              </div>
              <div className="config-field">
                <label>Model:</label>
                <select
                  value={settings.geminiConfig.model}
                  onChange={(e) => updateGeminiConfig({ model: e.target.value })}
                >
                  <option value="gemini-pro">gemini-pro</option>
                  <option value="gemini-pro-vision">gemini-pro-vision</option>
                </select>
              </div>
              <div className="config-field">
                <label>Temperature: {settings.geminiConfig.temperature}</label>
                <input
                  type="range"
                  min="0"
                  max="1"
                  step="0.1"
                  value={settings.geminiConfig.temperature}
                  onChange={(e) => updateGeminiConfig({ temperature: parseFloat(e.target.value) })}
                />
              </div>
            </div>
          )}

          {currentProvider === 'vllm' && (
            <div className="vllm-config">
              <h4>vLLM Configuration</h4>
              <div className="config-field">
                <label>Base URL:</label>
                <input
                  type="text"
                  value={settings.vllmConfig.baseUrl}
                  onChange={(e) => updateVLLMConfig({ baseUrl: e.target.value })}
                  placeholder="http://localhost:8000"
                />
              </div>
              <div className="config-field">
                <label>Model:</label>
                <input
                  type="text"
                  value={settings.vllmConfig.model}
                  onChange={(e) => updateVLLMConfig({ model: e.target.value })}
                  placeholder="llama-2-7b-chat"
                />
              </div>
              <div className="config-field">
                <label>Temperature: {settings.vllmConfig.temperature}</label>
                <input
                  type="range"
                  min="0"
                  max="1"
                  step="0.1"
                  value={settings.vllmConfig.temperature}
                  onChange={(e) => updateVLLMConfig({ temperature: parseFloat(e.target.value) })}
                />
              </div>
              <div className="config-field">
                <label>Max Tokens:</label>
                <input
                  type="number"
                  value={settings.vllmConfig.maxTokens}
                  onChange={(e) => updateVLLMConfig({ maxTokens: parseInt(e.target.value) })}
                  min="100"
                  max="4000"
                />
              </div>
            </div>
          )}

          <div className="config-status">
            {isConfigured() ? (
              <span className="status-ok">✅ Configured</span>
            ) : (
              <span className="status-error">❌ Configuration Required</span>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default LLMSettings;
